const HEADER = [
  '# Generated by `sops-env materialize` — do not edit.',
  '# Source of truth: the encrypted store (SOPS + age).',
  '# Change a value with `sops-env set` or `sops-env edit <environment>`, then regenerate.',
  '',
].join('\n');

/** Whether `text` opens with the header `formatEnvFile` writes. */
export function isGeneratedEnvFile(text) {
  return text.split(/\r?\n/, 1)[0] === HEADER.split('\n', 1)[0];
}

/**
 * Serialize a projected environment as dotenv text.
 *
 * Every value is double-quoted and escaped rather than emitted bare: a value
 * containing a space, a `#`, or a newline is common enough (trusted-origin
 * lists, private keys) and each one breaks a different dotenv parser in a
 * different way. Keys are sorted so regenerating produces no spurious diff.
 */
export function formatEnvFile(env) {
  const lines = Object.keys(env)
    .sort()
    .map((key) => `${key}=${quote(env[key])}`);

  return `${HEADER}${lines.join('\n')}\n`;
}

function quote(value) {
  const escaped = String(value)
    .replaceAll('\\', '\\\\')
    .replaceAll('"', '\\"')
    .replaceAll('\n', '\\n')
    .replaceAll('\r', '\\r');

  return `"${escaped}"`;
}
